const data = $input.item.json.data ?? '';
const statusCode = $input.item.json.statusCode ?? 0;

const indicators = [
  { re: /PerimeterX|_pxParam|px-captcha|pxCaptcha|_px\b/, name: 'PerimeterX' },
  { re: /cf_chl_|cf-browser-verification|__cf_chl_|Just a moment\.\.\.|Enable JavaScript and cookies to continue/, name: 'Cloudflare Challenge' },
  { re: /DataDome|datadome\.co/, name: 'DataDome' },
  { re: /incapsula|visid_incap|reese84/, name: 'Imperva/Incapsula' },
  { re: /AkamaiGHost|akamai_bot/, name: 'Akamai Bot Manager' },
  { re: /human\.security|shape\.service|f5bot/, name: 'F5/Shape Security' },
  { re: /verifyHuman|Are you a human|robot check|robotcheck|Pardon Our Interruption/, name: 'Generic Bot Check' }
];

let blockType = null;
for (const ind of indicators) {
  if (ind.re.test(data)) { blockType = ind.name; break; }
}

const isRealHtml = /<html|<body|<!DOCTYPE/i.test(data);
const isJsonBlob = /^\s*[\{\[]/.test(data) && !data.includes('<');
const isTiny = data.trim().length < 800 && !isRealHtml;
const isBlocked = !!blockType || isJsonBlob || isTiny;
const effectiveBlockType = blockType || (isBlocked ? 'Página bloqueada ou resposta inválida' : null);

return [{ json: {
  ...($input.item.json),
  is_bot_blocked: isBlocked,
  block_type: effectiveBlockType,
  html_length: data.length,
  is_real_html: isRealHtml
}}];

