const item = $input.item.json;
// If upstream node failed, item may contain 'error' key from n8n
const upstreamError = item.error?.message ?? item.errorMessage ?? null;
const raw = item.output ?? '';

if (upstreamError && !raw) {
  return { json: {
    error: true,
    message: 'Erro no agente LLM: ' + upstreamError,
    url: (() => { try { return $('Prepare Context').item.json.url; } catch(e){ return ''; } })()
  }};
}

try {
  const match = raw.match(/\{[\s\S]*\}/);
  if (!match) throw new Error('JSON nao encontrado na resposta do modelo.');
  const d = JSON.parse(match[0]);
  return { json: { ...d, url: (() => { try { return $('Prepare Context').item.json.url; } catch(e){ return d.url ?? ''; } })() } };
} catch(e) {
  return { json: {
    error: true,
    message: 'Falha ao processar resposta: ' + e.message,
    raw_preview: raw.substring(0, 500),
    url: (() => { try { return $('Prepare Context').item.json.url; } catch(e2){ return ''; } })()
  }};
}

const body = $input.first()?.json?.body ?? $input.first()?.json ?? {};
const url = (body.url ?? '').trim();
const context = (body.context ?? '').trim() || 'Nao informado';
const jobId = (body.jobId ?? '').trim();
if (!url) throw new Error('URL obrigatoria.');
if (!jobId) throw new Error('jobId obrigatorio.');
return [{ json: { url, context, jobId } }];

const query = $('GET - Poll').first()?.json?.query ?? {};
const jobId = (query.jobId ?? '').trim();
if (!jobId) return [{ json: { status: 'error', message: 'jobId obrigatorio' } }];
const row = $input.first()?.json ?? {};
if (!row.result) return [{ json: { status: 'processing' } }];
const r = row.result;
const parsed = typeof r === 'string' ? JSON.parse(r) : r;
return [{ json: { status: 'done', result: parsed } }];
